    Map<Integer,RuleKey> idToRuleKey=Stream.concat(alreadyLoadedRules.stream(),dbClient.ruleDao().selectDefinitionByIds(dbSession,Collections2.transform(ruleKeysToLoad,Integer::parseInt)).stream()).collect(Collectors.toMap(RuleDefinitionDto::getId,RuleDefinitionDto::getKey));
    LinkedHashMap<String,Long> newRulesFacet=new LinkedHashMap<>();
    rulesFacet.forEach((k,v) -> {
      RuleKey ruleKey=idToRuleKey.get(Integer.parseInt(k));
      if (ruleKey != null) {
        newRulesFacet.put(ruleKey.toString(),v);
      }
 else {
        LOGGER.error("Rule with id {} is not available in database",k);
      }
    }
);
    rulesFacet.clear();
    rulesFacet.putAll(newRulesFacet);
  }
 }

