        node.setSize(size);
      }
 catch (      NumberFormatException e) {
        report.logIssue(new Issue(NbBundle.getMessage(ImporterGEXF.class,"importerGEXF_error_nodesize",nodeId),Issue.Level.WARNING));
      }
    }
