 else       if (edgeType.equals("dou")) {
        edge.setType(EdgeDraft.EdgeType.MUTUAL);
      }
 else {
        report.logIssue(new Issue(NbBundle.getMessage(ImporterGEXF.class,"importerGEXF_error_edgetype",edgeType),Issue.Level.SEVERE));
