      imessage.setFlag(Flags.Flag.DELETED,true);
      ifolder.expunge();
    }
    MimeMessageEx icopy=MessageHelper.from(this,message,attachments,isession);
    Folder itarget=istore.getFolder(target.name);
    itarget.appendMessages(new Message[]{icopy});
  }
}

