@Override public void onReceive(Context context,Intent intent){
  try {
    String event=intent.getAction();
    Log_OC.d(TAG,"Received broadcast " + event);
    String accountName=intent.getStringExtra(FileSyncAdapter.EXTRA_ACCOUNT_NAME);
    String synchFolderRemotePath=intent.getStringExtra(FileSyncAdapter.EXTRA_FOLDER_PATH);
    RemoteOperationResult synchResult=(RemoteOperationResult)DataHolderUtil.getInstance().retrieve(intent.getStringExtra(FileSyncAdapter.EXTRA_RESULT));
    boolean sameAccount=(getAccount() != null && accountName.equals(getAccount().name) && getStorageManager() != null);
    if (sameAccount) {
      if (FileSyncAdapter.EVENT_FULL_SYNC_START.equals(event)) {
        mSyncInProgress=true;
      }
 else {
        OCFile currentFile=(getFile() == null) ? null : getStorageManager().getFileByPath(getFile().getRemotePath());
        OCFile currentDir=(getCurrentDir() == null) ? null : getStorageManager().getFileByPath(getCurrentDir().getRemotePath());
        if (currentDir == null) {
          Toast.makeText(FileDisplayActivity.this,String.format(getString(R.string.sync_current_folder_was_removed),synchFolderRemotePath),Toast.LENGTH_LONG).show();
          browseToRoot();
        }
 else {
          if (currentFile == null && !getFile().isFolder()) {
            cleanSecondFragment();
            currentFile=currentDir;
          }
          if (currentDir.getRemotePath().equals(synchFolderRemotePath)) {
            OCFileListFragment fileListFragment=getListOfFilesFragment();
            if (fileListFragment != null) {
              fileListFragment.listDirectory(currentDir,MainApp.isOnlyOnDevice(),false);
            }
          }
          setFile(currentFile);
        }
        mSyncInProgress=(!FileSyncAdapter.EVENT_FULL_SYNC_END.equals(event) && !RefreshFolderOperation.EVENT_SINGLE_FOLDER_SHARES_SYNCED.equals(event));
        if (RefreshFolderOperation.EVENT_SINGLE_FOLDER_CONTENTS_SYNCED.equals(event) && synchResult != null && !synchResult.isSuccess()) {
          if (checkForRemoteOperationError(synchResult)) {
            requestCredentialsUpdate(context);
          }
 else           if (RemoteOperationResult.ResultCode.SSL_RECOVERABLE_PEER_UNVERIFIED.equals(synchResult.getCode())) {
            showUntrustedCertDialog(synchResult);
          }
        }
        removeStickyBroadcast(intent);
        DataHolderUtil.getInstance().delete(intent.getStringExtra(FileSyncAdapter.EXTRA_RESULT));
        Log_OC.d(TAG,"Setting progress visibility to " + mSyncInProgress);
        setIndeterminate(mSyncInProgress);
        setBackgroundText();
      }
    }
    if (synchResult != null && synchResult.getCode().equals(RemoteOperationResult.ResultCode.SSL_RECOVERABLE_PEER_UNVERIFIED)) {
      mLastSslUntrustedServerResult=synchResult;
    }
  }
 catch (  RuntimeException e) {
    removeStickyBroadcast(intent);
    DataHolderUtil.getInstance().delete(intent.getStringExtra(FileSyncAdapter.EXTRA_RESULT));
  }
}

