/** 
 * Checks whether any exceptions occurred during asynchronous frame processing and rethrows the first exception encountered.
 */
public void getAndRethrowBackgroundExceptions() throws TransformationException {
  @Nullable Future<?> oldestGlProcessingFuture=futures.peek();
  while (oldestGlProcessingFuture != null && oldestGlProcessingFuture.isDone()) {
    futures.poll();
    try {
      oldestGlProcessingFuture.get();
    }
 catch (    ExecutionException e) {
      throw TransformationException.createForFrameProcessorChain(e,TransformationException.ERROR_CODE_GL_PROCESSING_FAILED);
