  }
  if (adsManager == null) {
    Log.w(TAG,"Ignoring ad prepare error after release");
    return;
  }
  if (imaAdState == IMA_AD_STATE_NONE) {
    fakeContentProgressElapsedRealtimeMs=SystemClock.elapsedRealtime();
